            for(int i=0;i<3;i++){var col=new FlowLayoutPanel { Width=97,Height=58,FlowDirection=FlowDirection.TopDown,Margin=Padding.Empty };col.Controls.Add(ClxnStyle.Label("XYZ"[i].ToString(),8,ClxnStyle.Muted));clxnXYZ[i]=new NumericUpDown { Minimum=-1000000,Maximum=1000000,DecimalPlaces=3,Width=94,BackColor=ClxnStyle.Background,ForeColor=ClxnStyle.Text,Margin=Padding.Empty };col.Controls.Add(clxnXYZ[i]);coords.Controls.Add(col);}clxnLibrary.Controls.Add(coords);clxnLibrary.Controls.Add(ClxnStyle.Label("Поворот объекта (градусы)",9,ClxnStyle.Muted));clxnPinHeading=new NumericUpDown{Width=300,Minimum=-360,Maximum=360,DecimalPlaces=1,BackColor=ClxnStyle.Background,ForeColor=ClxnStyle.Text};clxnLibrary.Controls.Add(clxnPinHeading);
