        ClxnPin ClxnSelectedPin(){lock(ClxnProject.Sync)return ClxnProject.Pins.FirstOrDefault(p=>p.Id==clxnSelectedId);}
        void ClxnToggleLibrary(){clxnWardrobe.Visible=false;if(clxnEnvironment!=null)clxnEnvironment.Visible=false;clxnLogPanel.Visible=false;clxnFlightPanel.Visible=false;clxnLibrary.Visible=!clxnLibrary.Visible;if(clxnLibrary.Visible){clxnLibrary.Left=ClientSize.Width-clxnLibrary.Width+12;clxnLibrary.BringToFront();ClxnRefreshLibrary();if(clxnSelectedId!=null)ClxnSelectPin(clxnSelectedId);}}
        void ClxnSelectPin(string id){clxnWardrobe.Visible=false;if(clxnEnvironment!=null)clxnEnvironment.Visible=false;clxnLogPanel.Visible=false;clxnFlightPanel.Visible=false;clxnSelectedId=id;clxnLibrary.Visible=true;clxnLibrary.BringToFront();ClxnRefreshLibrary();var p=ClxnSelectedPin();if(p==null)return;clxnPinName.Text=p.Name;clxnPinNote.Text=p.Note;clxnXYZ[0].Value=(decimal)p.Position.X;clxnXYZ[1].Value=(decimal)p.Position.Y;clxnXYZ[2].Value=(decimal)p.Position.Z;clxnPinHeading.Value=(decimal)p.Heading;}
        void ClxnRefreshLibrary(){if(clxnPinList==null)return;clxnSelecting=true;clxnPinList.BeginUpdate();clxnPinList.Items.Clear();lock(ClxnProject.Sync){foreach(var p in ClxnProject.Pins)clxnPinList.Items.Add(p);clxnCount.Text="ОБЪЕКТЫ "+ClxnProject.Pins.Count+"   /   ЛИНИИ "+ClxnProject.Strokes.Count;var chosen=ClxnProject.Pins.FirstOrDefault(p=>p.Id==clxnSelectedId);if(chosen!=null)clxnPinList.SelectedItem=chosen;}clxnPinList.EndUpdate();clxnSelecting=false;clxnLibraryDirty=false;var selected=ClxnSelectedPin();if(selected==null){clxnSelectedId=null;clxnPinName.Text=clxnPinNote.Text="";foreach(var coordinate in clxnXYZ)coordinate.Value=0;clxnPinHeading.Value=0;}else if(!ClxnHasFocusedEditor(clxnLibrary)){clxnPinName.Text=selected.Name;clxnPinNote.Text=selected.Note;clxnXYZ[0].Value=(decimal)selected.Position.X;clxnXYZ[1].Value=(decimal)selected.Position.Y;clxnXYZ[2].Value=(decimal)selected.Position.Z;clxnPinHeading.Value=(decimal)selected.Heading;}ClxnShowPose();}
        void ClxnRefreshButtons(){if(clxnToolButtons==null)return;foreach(var b in clxnToolButtons.Controls.OfType<Button>())if(b.Tag is string mode){b.BackColor=mode==ClxnTool?ClxnStyle.Accent:ClxnStyle.Surface;b.ForeColor=mode==ClxnTool?ClxnStyle.OnAccent:ClxnStyle.Text;}}
        void ClxnOpenProject(){if(clxnFlightPlaying)ClxnStopFlight();if(clxnWalking)ClxnLeaveWalk();ClxnFinishStroke();using(var d=new OpenFileDialog { Filter="Проект 666clxn|*.clxn" })if(d.ShowDialog(this)==DialogResult.OK)try{var text=File.ReadAllText(d.FileName);var check=new ClxnDocument();check.Deserialize(text);ClxnProject.Checkpoint();ClxnProject.Deserialize(text);ClxnProject.SavePath=d.FileName;ClxnProject.TrackPath(d.FileName);clxnSelectedId=null;ClxnProject.Commit();ClxnRestoreSceneView();clxnMessage="✓ Сцена загружена: рисунки, метки и персонажи восстановлены.";}catch(Exception ex){clxnMessage="Не удалось открыть: "+ex.Message;}}
        void ClxnSaveProject(){if(clxnFlightPlaying)ClxnStopFlight();if(clxnWalking)ClxnLeaveWalk();ClxnFinishStroke();lock(RenderSyncRoot){ClxnProject.ViewPosition=camera.Position;ClxnProject.ViewRotation=camera.TargetRotation;}using(var d=new SaveFileDialog { Filter="Проект 666clxn|*.clxn",FileName="Мой 3D проект.clxn" })if(d.ShowDialog(this)==DialogResult.OK)try{ClxnProject.Save(d.FileName);ClxnProject.SavePath=d.FileName;clxnMessage="✓ Сцена сохранена: "+Path.GetFileName(d.FileName);}catch(Exception ex){clxnMessage="Ошибка сохранения: "+ex.Message;}}
        void ClxnUpdateProjectedPins(){
            var result=new List<ClxnProjectedPin>();
            lock(ClxnProject.Sync)foreach(var pin in ClxnProject.Pins){var anchor=pin.Position+(string.IsNullOrEmpty(pin.Model)?Vector3.Zero:new Vector3(0,0,2));if(!ClxnVisibility.LabelWithinRange(camera.Position,anchor))continue;var rel=anchor-camera.Position;if(Vector3.Dot(rel,camera.ViewDirection)<=0)continue;var sp=camera.ViewProjMatrix.MultiplyW(rel);if(sp.Z<=0 || Math.Abs(sp.X)>1 || Math.Abs(sp.Y)>1)continue;float distance=rel.Length();result.Add(new ClxnProjectedPin { Id=pin.Id,Text=pin.Name+"  ·  "+distance.ToString("0")+" м",Point=new Point((int)((sp.X*.5f+.5f)*camera.Width)+14,(int)((-.5f*sp.Y+.5f)*camera.Height)-17),Colour=pin.Colour,Distance=distance });}
            result.AddRange(clxnZoneProjected);
            lock(clxnProjectionSync)clxnProjected=result.OrderBy(p=>p.Id.StartsWith("zone:",StringComparison.Ordinal)?1:0).ThenBy(p=>p.Distance).Take(48).ToList();
        }
        string ClxnHitLabel(Point p){return clxnPinLabels.FirstOrDefault(l=>l.Visible&&l.Bounds.Contains(p))?.Tag as string;}
        void ClxnRefreshLabels(){if(clxnHud==null||IsDisposed)return;
            List<ClxnProjectedPin> projected;lock(clxnProjectionSync)projected=clxnProjected.OrderBy(p=>p.Id.StartsWith("zone:",StringComparison.Ordinal)?1:0).ThenBy(p=>p.Id,StringComparer.Ordinal).ToList();
            while(clxnPinLabels.Count<projected.Count){var label=new Label { Size=new Size(190,24),BackColor=ClxnStyle.Surface,Font=new Font("Segoe UI",9),AutoEllipsis=true,Cursor=Cursors.Hand,TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(6,0,0,0) };label.Click+=(s,e)=>{var id=(string)label.Tag;if(id!=null&&!id.StartsWith("zone:",StringComparison.Ordinal))ClxnSelectPin(id);};Controls.Add(label);clxnPinLabels.Add(label);}
            var occupied=new List<Rectangle>{clxnHud.Bounds,clxnRail.Bounds,clxnOptions.Bounds,clxnHint.Bounds};if(clxnEnvironment.Visible)occupied.Add(clxnEnvironment.Bounds);if(clxnWardrobe.Visible)occupied.Add(clxnWardrobe.Bounds);if(clxnLibrary.Visible)occupied.Add(clxnLibrary.Bounds);if(clxnLogPanel.Visible)occupied.Add(clxnLogPanel.Bounds);if(clxnFlightPanel.Visible)occupied.Add(clxnFlightPanel.Bounds);if(ToolsPanel.Visible)occupied.Add(ToolsPanel.Bounds);
            var active=new HashSet<Label>();foreach(var pin in projected){var label=clxnPinLabels.FirstOrDefault(l=>(string)l.Tag==pin.Id&&!active.Contains(l))??clxnPinLabels.First(l=>!active.Contains(l)&&!projected.Any(p=>p.Id==(string)l.Tag));active.Add(label);if(!ClxnVisible || clxnWalking || clxnFlightPlaying || clxnUiCollapsed){label.Visible=false;continue;}var rect=new Rectangle(pin.Point,label.Size);bool visible=ClientRectangle.Contains(rect)&&!occupied.Any(r=>r.IntersectsWith(rect));if(label.Visible!=visible)label.Visible=visible;if(!visible)continue;occupied.Add(rect);if(label.Location!=pin.Point)label.Location=pin.Point;if(label.Text!=pin.Text)label.Text=pin.Text;label.Tag=pin.Id;var ink=Color.FromArgb(pin.Colour);label.ForeColor=ClxnStyle.Dark&&ink.GetBrightness()<.35f?ClxnStyle.Text:ink;}

            foreach(var label in clxnPinLabels)if(!active.Contains(label)&&label.Visible)label.Visible=false;
        }
        void ClxnUiTick(){if(clxnEnvironmentDirty&&initialised&&clxnSceneRestored&&!clxnFlightPlaying){clxnEnvironmentDirty=false;ClxnApplyEnvironment();}if(clxnClearPending&&!clxnExporting){clxnClearPending=false;ClxnClearScene();}
            if(IsDisposed || !IsHandleCreated)return;
            var mouse=PointToClient(System.Windows.Forms.Cursor.Position);clxnPointerOnMap=ClientRectangle.Contains(mouse)&&GetChildAtPoint(mouse)==null;
            if(initialised&&!clxnStartupSettle.IsRunning)clxnStartupSettle.Start();
            if(initialised&&!clxnSceneRestored&&clxnStartupSettle.ElapsedMilliseconds>1500){clxnSceneRestored=true;try{ClxnApplyPerformance(clxnPerformance,false);ClxnRestoreSceneView();}catch(Exception ex){clxnMessage=ex.Message;}}
            if(clxnLibraryDirty){ClxnRefreshLibrary();ClxnRefreshKeys();}ClxnPanelsTick();ClxnWardrobeTick();if(ClxnProject.LastError!=null)clxnJournal.Add(ClxnProject.LastError);
            clxnHint.Text=ClxnProject.LastError??(!initialised?"Загрузка карты и коллизий… Дождитесь появления мира.":clxnMessage);
            var p=ClxnCameraPosition;clxnCoords.Text="XYZ  "+ClxnDocument.Coords(p)+"   ·   "+Path.GetFileName(ClxnProject.SavePath)+"   ·   "+(string.IsNullOrEmpty(ClxnProject.MapProjectPath)?"Карта GTA V":"Внешняя карта")+"   ·   "+(ClxnProject.ZoneMode=="mcl"?"ЗОНЫ MCL":ClxnProject.ZoneMode=="capt"?"КАПТ-ЗОНЫ":"Обычный вид");
            
            clxnHint.Visible=!clxnWalking&&!clxnFlightPlaying;if(clxnEnvironment.Visible)clxnEnvironment.BringToFront();if(clxnWardrobe.Visible)clxnWardrobe.BringToFront();clxnWalkHint.BringToFront();clxnHud.BringToFront();clxnOptions.BringToFront();clxnRail.BringToFront();if(clxnLibrary.Visible)clxnLibrary.BringToFront();if(clxnLogPanel.Visible)clxnLogPanel.BringToFront();if(clxnFlightPanel.Visible)clxnFlightPanel.BringToFront();if(clxnFlightPlaying)clxnPlaybackBar.BringToFront();ClxnPresentationTick();
        }
    }
}







